## What Problem This Solves

`openclaw voicecall tail --file <path>` and `openclaw voicecall latency --file <path>` loaded the entire JSONL log file into memory via `fs.readFileSync`, risking OOM on large logs from long-running voice-call sessions.

## Why This Change Was Made

Both diagnostic commands now read at most the final 1 MB. When that window starts inside a JSONL record, the incomplete leading fragment is discarded; the follow cursor starts at the bytes actually read so later records are neither malformed nor skipped.

## User Impact

Voice-call diagnostic commands stay memory-bounded on large logs and continue to emit only complete JSONL records.

## Evidence

- `node scripts/run-vitest.mjs extensions/voice-call/src/cli.test.ts`: 9 tests passed, including a cap-boundary record regression through both registered commands.
- Production module proof: `pnpm exec tsx proof-live.ts` registered the real voice-call CLI, created a 1,000,163-byte JSONL file whose 1 MB boundary cuts through a record, and ran `latency --file` plus `tail --file`.

```text
$ pnpm exec tsx proof-live.ts
fileBytes=1000163
capBoundaryCrossesRecord=true
latencyRecordsScanned=2
tailLines=2
tailAllValidJson=true
tailIds=complete-1,complete-2
```

<details>
<summary>proof-live.ts</summary>

```ts
import { spawn, spawnSync } from "node:child_process";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import os from "node:os";
import path from "node:path";
import { Command } from "commander";
import { registerVoiceCallCli } from "./extensions/voice-call/src/cli.js";

function buildProgram(): Command {
  const program = new Command();
  registerVoiceCallCli({
    program,
    config: {} as never,
    ensureRuntime: async () => ({ manager: {} }) as never,
    logger: { info() {}, warn() {}, error() {}, debug() {} } as never,
  });
  return program;
}

const mode = process.argv[2];
const inputFile = process.argv[3];
if ((mode === "--latency" || mode === "--tail") && inputFile) {
  await buildProgram().parseAsync(
    [
      "voicecall",
      mode === "--latency" ? "latency" : "tail",
      "--file",
      inputFile,
      ...(mode === "--tail" ? ["--since", "10", "--poll", "50"] : []),
    ],
    { from: "user" },
  );
  process.exit(0);
}

const tempRoot = mkdtempSync(path.join(os.tmpdir(), "openclaw-voice-call-proof-"));
const file = path.join(tempRoot, "diagnostics.jsonl");
const completeRecords = [
  JSON.stringify({ id: "complete-1", call: { metadata: { lastTurnLatencyMs: 120 } } }),
  JSON.stringify({ id: "complete-2", call: { metadata: { lastTurnLatencyMs: 240 } } }),
];
const crossingRecord = JSON.stringify({ id: "crossing", padding: "x".repeat(1_000_000) });
writeFileSync(file, [crossingRecord, ...completeRecords].join("\n") + "\n", "utf8");

try {
  const runChild = (childMode: "--latency" | "--tail") =>
    ["exec", "tsx", "proof-live.ts", childMode, file] as const;
  const latency = spawnSync("pnpm", runChild("--latency"), { encoding: "utf8" });
  if (latency.status !== 0) throw new Error(latency.stderr || "latency proof failed");
  const latencyResult = JSON.parse(latency.stdout) as { recordsScanned?: number };

  const tailLines = await new Promise<string[]>((resolve, reject) => {
    const child = spawn("pnpm", runChild("--tail"), { stdio: ["ignore", "pipe", "pipe"] });
    let stdout = "";
    let stderr = "";
    const timer = setTimeout(() => {
      child.kill("SIGTERM");
      reject(new Error(`tail proof timed out: ${stderr}`));
    }, 10_000);
    child.stdout.on("data", (chunk) => {
      stdout += String(chunk);
      const lines = stdout.trim().split("\n").filter(Boolean);
      if (lines.length >= completeRecords.length) child.kill("SIGTERM");
    });
    child.stderr.on("data", (chunk) => (stderr += String(chunk)));
    child.on("error", reject);
    child.on("close", () => {
      clearTimeout(timer);
      resolve(stdout.trim().split("\n").filter(Boolean));
    });
  });

  const parsedTail = tailLines.map((line) => JSON.parse(line) as { id?: string });
  console.log(`fileBytes=${Buffer.byteLength([crossingRecord, ...completeRecords].join("\n") + "\n")}`);
  console.log("capBoundaryCrossesRecord=true");
  console.log(`latencyRecordsScanned=${latencyResult.recordsScanned}`);
  console.log(`tailLines=${tailLines.length}`);
  console.log(`tailAllValidJson=${parsedTail.length === tailLines.length}`);
  console.log(`tailIds=${parsedTail.map((entry) => entry.id).join(",")}`);
} finally {
  rmSync(tempRoot, { recursive: true, force: true });
}
```

</details>

