  const rederived = Symbol.for("openclaw.taskRegistry.codexNativeSubagentCancel");
  console.log("5. Symbol key matches:", CANCEL_KEY === rederived);
  console.log("   description:", CANCEL_KEY.description);

  // 6. runId→childThreadId extraction
  console.log("6. codex runId:", JSON.stringify({ runId: "codex-thread:ct-789", childId: "codex-thread:ct-789".startsWith("codex-thread:") ? "codex-thread:ct-789".slice("codex-thread:".length) : undefined }));
